using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO.Compression;
namespace KingswayWorkshop;
public sealed partial class Store {
 public readonly string Root,GameRoot,Original;public Catalog Catalog;public string LastBuild=>Path.Combine(Root,"Builds","release.win");
 public Store(string root,string gameRoot){Root=root;GameRoot=gameRoot;Original=Game.OriginalPath(gameRoot);foreach(var d in new[]{"Projects","Mods","Builds","Recovery","Evidence","Catalog","Exports"})Directory.CreateDirectory(Path.Combine(root,d));Game.VerifyOriginal(Original);Catalog=Json.Read<Catalog>(Path.Combine(root,"Catalog","catalog.json"));string sounds=Path.Combine(gameRoot,"KingswayModdingV2","Catalog","source","gml_Script_scr_LoadSounds.gml");if(File.Exists(sounds))Catalog.SoundNames=System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(sounds),@"global\.(sound_\w+) = (\d+);").Select(x=>x.Groups[1].Value).ToHashSet();string music=Path.Combine(gameRoot,"Music");if(Directory.Exists(music))Catalog.MusicNames=Directory.GetFiles(music,"*.ogg").Select(Path.GetFileNameWithoutExtension).ToHashSet();Adapters.Configure(Catalog);PreserveV1();}
 void PreserveV1(){string dest=Path.Combine(Root,"Recovery","v1-verified.win"),metadata=Path.Combine(GameRoot,"KingswayModding","installed.json");if(File.Exists(dest)||!File.Exists(metadata))return;string expected=V1Hash();foreach(string source in new[]{Path.Combine(GameRoot,"data.win"),Path.Combine(GameRoot,"KingswayModding","work","patched.win")})if(File.Exists(source)&&Game.Hash(source)==expected){File.Copy(source,dest);File.Copy(metadata,Path.Combine(Root,"Recovery","v1-installed.json"),true);return;}}
 public object ReadGml(string id,string file){if(!System.Text.RegularExpressions.Regex.IsMatch(file??"",@"^[a-z][a-z0-9_]*\.gml$"))throw new Exception("Invalid GML filename");var path=Validation.Within(Project(id),file,false);return new{source=File.Exists(path)?File.ReadAllText(path):"",exists=File.Exists(path)};}
 public string Project(string id,string kind="Projects"){if(!Validation.Identifier(id))throw new Exception("Invalid project ID");return Path.Combine(Root,kind,id);}
 public List<Manifest> List(string kind="Projects"){var list=new List<Manifest>();foreach(var d in Directory.GetDirectories(Path.Combine(Root,kind)).Order(StringComparer.Ordinal)){var p=Path.Combine(d,"mod.json");if(!File.Exists(p))continue;var m=Revision.Load(this,p);m.Directory=d;list.Add(m);}return list;}
 public Dictionary<string,bool> Enabled()=>File.Exists(Path.Combine(Root,"enabled.json"))?Json.Read<Dictionary<string,bool>>(Path.Combine(Root,"enabled.json")):new();
 public void Enable(string id,bool enabled){if(!List("Mods").Any(x=>x.Id==id))throw new Exception("Mod not found");var e=Enabled();e[id]=enabled;Json.Save(Path.Combine(Root,"enabled.json"),e);}
 public void Save(Manifest m){Revision.Upgrade(m);if(!Validation.Identifier(m.Id))throw new Exception("Invalid mod ID");var dir=Project(m.Id);Directory.CreateDirectory(dir);m.Directory=dir;Json.Save(Path.Combine(dir,"mod.json"),m);}
 public List<ValidationError> ValidateProject(string id){var m=List().First(x=>x.Id==id);return Validation.Check(new(){m},Catalog);}
 public void Stage(string id){var m=List().First(x=>x.Id==id);var errors=Validation.Check(new(){m},Catalog);if(errors.Count>0)throw new Exception(Json.Text(new{errors}));string target=Project(id,"Mods");Directory.CreateDirectory(target);CopyProject(m.Directory,target);Enable(id,true);}
 static void CopyProject(string source,string target){foreach(var p in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){var rel=Path.GetRelativePath(source,p);var src=Validation.Within(source,rel);var dst=Validation.Within(target,rel,false);Directory.CreateDirectory(Path.GetDirectoryName(dst)!);File.Copy(src,dst,true);}}
 public byte[] Export(string id){var m=List().First(x=>x.Id==id);var errors=Validation.Check(new(){m},Catalog);if(errors.Count>0)throw new Exception(Json.Text(new{errors}));using var ms=new MemoryStream();using(var zip=new ZipArchive(ms,ZipArchiveMode.Create,true)){foreach(var p in Directory.GetFiles(m.Directory,"*",SearchOption.AllDirectories).Order(StringComparer.Ordinal)){var rel=Path.GetRelativePath(m.Directory,p).Replace('\\','/');Validation.Within(m.Directory,rel);var entry=zip.CreateEntry(rel,CompressionLevel.Optimal);entry.LastWriteTime=new DateTimeOffset(2000,1,1,0,0,0,TimeSpan.Zero);using var stream=entry.Open();using var file=File.OpenRead(p);file.CopyTo(stream);}}return ms.ToArray();}
 public string Import(byte[] bytes){if(bytes.Length>64*1024*1024)throw new Exception("Archive exceeds 64 MB");var temp=Path.Combine(Root,"Builds","import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{using var zip=new ZipArchive(new MemoryStream(bytes),ZipArchiveMode.Read);if(zip.Entries.Count>512)throw new Exception("Archive has too many entries");long total=0;var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in zip.Entries){if(entry.FullName.EndsWith('/'))continue;if(!names.Add(entry.FullName.Replace('\\','/')))throw new Exception("Duplicate archive path");int type=(entry.ExternalAttributes>>16)&0xF000;if(type==0xA000)throw new Exception("Archive links are forbidden");total+=entry.Length;if(total>128*1024*1024||entry.Length>32*1024*1024)throw new Exception("Uncompressed archive exceeds limit");var target=Validation.Within(temp,entry.FullName,false);if(!new[]{".json",".png",".gml",".md",".txt",".wav",".ogg"}.Contains(Path.GetExtension(target).ToLowerInvariant()))throw new Exception("Archive contains unsupported file: "+entry.FullName);Directory.CreateDirectory(Path.GetDirectoryName(target)!);using var from=entry.Open();using var to=File.Create(target);from.CopyTo(to);}
  var m=Revision.Load(this,Path.Combine(temp,"mod.json"));m.Directory=temp;var errors=Validation.Check(new(){m},Catalog);if(errors.Count>0)throw new Exception(Json.Text(new{errors}));var dest=Project(m.Id,"Mods");if(Directory.Exists(dest))throw new Exception("A managed mod with ID "+m.Id+" already exists; edit its project and use Add to manager");Directory.Move(temp,dest);var project=Project(m.Id);if(!Directory.Exists(project)){Directory.CreateDirectory(project);CopyProject(dest,project);}Enable(m.Id,true);return m.Id;
 }finally{if(Directory.Exists(temp))Directory.Delete(temp,true);}}
 public List<Manifest> Active(){var enabled=Enabled();return List("Mods").Where(m=>!enabled.TryGetValue(m.Id,out bool e)||e).ToList();}
 public object Build(bool test=false,string projectId="",string enemyId="",FightOptions fight=null,bool minimizeOnly=false){using var mutation=MutationLock();string output=test?Path.Combine(GameRoot,fight==null?"data.v2-test.win":"data.v2-fight.win"):LastBuild;string staging=output+".staging";try{Game.VerifyOriginal(Original);string preview="";var active=test?new List<Manifest>():Active();if(test){active=new(){EngineTests.Fixture(Root)};if(fight==null&&projectId=="")MinimizeTests.AddProjects(this,active);if(fight!=null)preview=Compiler.Obj(active[0],fight.Verify=="hazardclose"?"hazard":"head");if(projectId!=""){var chosen=List().First(x=>x.Id==projectId);var selected=chosen.Enemies.First(x=>x.Id==enemyId);active=new(){chosen};if(selected.Mode=="cosmetic"){string host="workshop_cosmetic_host";for(int i=2;chosen.Enemies.Any(e=>e.Id==host);i++)host="workshop_cosmetic_host_"+i;chosen.Enemies.Add(new(){Id=host,Name="Cosmetic test host",Stats=new(){MaxHealth=10000,AttackSpeed=0},Actions=new(),Components=new(){new(){Enemy=selected.Id,Role="limb"}}});preview=Compiler.Obj(chosen,host);}else preview=Compiler.Obj(chosen,selected.Id);
     // A playable test of a boss/quest replacement fights the native slot, so its native quest drops and flags apply.
     var slot=chosen.Overrides.FirstOrDefault(o=>o.Enemy==selected.Id&&Adapters.Single.Contains(o.Slot)&&!Adapters.Endgame.Contains(o.Slot))?.Slot;if(fight!=null&&slot!=null)preview=slot;}}
string key=test?BuildKey(active,preview,fight,minimizeOnly,projectId,enemyId):"";
if(test&&CachedBuild(output,key) is {} cached)return cached;
using var g=new Game(Original);var c=new Compiler(g,Catalog,Root){Fight=fight,MinimizeOnly=minimizeOnly,PreviewEnemy=preview};
var report=c.Build(active,staging,test);if(test)File.Delete(output+".key");File.Move(staging,output,true);File.Move(staging+".json",output+".json",true);if(test)File.WriteAllText(output+".key",key);return report;}finally{if(File.Exists(staging))File.Delete(staging);}}
 // A test build is a pure function of these inputs, so an unchanged set reuses the last build.
 string BuildKey(List<Manifest> active,string preview,FightOptions fight,bool minimizeOnly,string projectId,string enemyId){
  var text=new StringBuilder();
  void Add(string path)=>text.Append(path).Append(' ').Append(Game.Hash(path)).Append('\n');
  Add(typeof(Store).Assembly.Location);
  Add(Path.Combine(Root,"Catalog","catalog.json"));
  foreach(var p in Directory.GetFiles(Path.Combine(Root,"Runtime"),"*",SearchOption.AllDirectories).Order(StringComparer.Ordinal))Add(p);
  // Test harness scripts are compiled into test builds too.
  foreach(var p in Directory.GetFiles(Path.Combine(Root,"Tests"),"*.gml",SearchOption.AllDirectories).Order(StringComparer.Ordinal))Add(p);
  foreach(var m in active)foreach(var p in Directory.GetFiles(m.Directory,"*",SearchOption.AllDirectories).Order(StringComparer.Ordinal))Add(p);
  text.Append(Json.Text(new{original=Game.OriginalHash,fight,minimizeOnly,projectId,enemyId,preview,mods=active,sounds=Catalog.SoundNames?.Order(StringComparer.Ordinal),music=Catalog.MusicNames?.Order(StringComparer.Ordinal)}));
  return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(text.ToString())));
 }
 object CachedBuild(string output,string key){
  if(!File.Exists(output)||!File.Exists(output+".json")||!File.Exists(output+".key")||File.ReadAllText(output+".key")!=key)return null;
  using var json=JsonDocument.Parse(File.ReadAllText(output+".json"));
  return Game.Hash(output)==json.RootElement.GetProperty("sha256").GetString()?json.RootElement.Clone():null;
 }
 FileStream MutationLock()=>new FileStream(Path.Combine(Root,"Builds","mutation.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);
 public static void Closed(){if(Process.GetProcessesByName("Kingsway").Length>0)throw new Exception("Close Kingsway before installation, restoration, or isolated testing.");}
 public object Status(){string active=Game.Hash(Path.Combine(GameRoot,"data.win"));return new{originalSha256=Game.OriginalHash,activeSha256=active,recognized=Known(active),gameRunning=Process.GetProcessesByName("Kingsway").Length>0,installed=active==Game.OriginalHash?"original":active==V1Hash()?"V1":Known(active)?"V2":"external change",v1Available=File.Exists(Path.Combine(Root,"Recovery","v1-verified.win")),enabled=Enabled(),mods=List("Mods").Select(m=>new{m.Id,m.Name,m.Version}).ToArray(),lastBuild=File.Exists(LastBuild+".json")?JsonDocument.Parse(File.ReadAllText(LastBuild+".json")).RootElement.Clone():default(JsonElement?)};}
 string V1Hash(){var p=Path.Combine(GameRoot,"KingswayModding","installed.json");return File.Exists(p)?JsonDocument.Parse(File.ReadAllText(p)).RootElement.GetProperty("sha256").GetString()!:"";}
 bool Known(string hash){if(hash==Game.OriginalHash||hash==V1Hash())return true;foreach(var p in new[]{Path.Combine(Root,"installed.json"),Path.Combine(Root,"Recovery","journal.json")})if(File.Exists(p)){var j=JsonDocument.Parse(File.ReadAllText(p)).RootElement;foreach(string n in new[]{"sha256","before","after"})if(j.TryGetProperty(n,out var v)&&v.GetString()==hash)return true;}return false;}
 public object Install(bool restore=false,bool v1=false){using var mutation=MutationLock();Closed();Game.VerifyOriginal(Original);string source=restore?Original:v1?Path.Combine(Root,"Recovery","v1-verified.win"):LastBuild;if(!File.Exists(source))throw new Exception("Build first");if(v1&&Game.Hash(source)!=V1Hash())throw new Exception("V1 recovery checksum mismatch");if(!restore&&!v1){var report=JsonDocument.Parse(File.ReadAllText(source+".json")).RootElement;if(report.GetProperty("testBuild").GetBoolean()||report.GetProperty("sha256").GetString()!=Game.Hash(source))throw new Exception("Unverified or test build cannot be installed");using var verify=new Game(source);if(verify.Data.GeneralInfo.Name.Content!="Kingsway")throw new Exception("Invalid release identity");}
  string dest=Path.Combine(GameRoot,"data.win"),before=Game.Hash(dest),after=Game.Hash(source);if(!Known(before))throw new Exception("External change detected in data.win; preserve and resolve it before installation");var staged=Path.Combine(GameRoot,"data.v2-install.tmp");File.Copy(source,staged,true);if(Game.Hash(staged)!=after)throw new Exception("Staging checksum mismatch");Closed();if(Game.Hash(dest)!=before)throw new Exception("Game data changed during staging");string recovery=Path.Combine(Root,"Recovery",before+".win");if(!File.Exists(recovery))File.Copy(dest,recovery);Json.Save(Path.Combine(Root,"Recovery","journal.json"),new{before,after,phase="prepared",recovery});File.Replace(staged,dest,null);if(Game.Hash(dest)!=after)throw new Exception("Installed checksum mismatch; use recovery journal");Json.Save(Path.Combine(Root,"installed.json"),new{sha256=after,originalSha256=Game.OriginalHash});Json.Save(Path.Combine(Root,"Recovery","journal.json"),new{before,after,phase="committed",recovery});return new{sha256=after,restoredOriginal=after==Game.OriginalHash};
 }

}
